INSERT INTO `setting_definitions` VALUES
(1,'month_start_day','بداية الشهر المالي','Month Start Day','حدد اليوم الذي يبدأ به الشهر المالي لاحتساب الرواتب (من 1 إلى 31)','Select the fiscal month start day for payroll (1–31)','FontAwesomeIcons.calendarDay',0,1,1,'2026-05-17 06:49:17'),
(2,'month_end_day','نهاية الشهر المالي','Month End Day','حدد اليوم الذي ينتهي به الشهر المالي لاحتساب الرواتب (من 1 إلى 31)','Select the fiscal month end day for payroll (1–31)','FontAwesomeIcons.calendarCheck',0,1,2,'2026-05-17 06:49:20'),
(3,'weekly_off_days','أيام الراحة الأسبوعية','Weekly Off Days','اختر أيام الراحة الأسبوعية المعتمدة في الشركة','Select the weekly rest days used in your company','FontAwesomeIcons.calendarWeek',1,0,3,'2026-05-17 05:05:49'),
(4,'overtime_rate','معدل احتساب الأوفرتايم','Overtime Rate','اختر طريقة احتساب ساعات العمل الإضافية','Choose how overtime hours are calculated','FontAwesomeIcons.businessTime',0,1,4,'2026-05-17 06:49:29'),
(5,'monthly_leave_accrual','رصيد الإجازة الشهري (أيام)','Monthly Leave Accrual','عدد أيام الإجازة المستحقة شهرياً لكل موظف','Number of leave days accrued per month for each employee','FontAwesomeIcons.umbrellaBeach',0,0,5,'2026-05-17 06:49:31'),
(6,'pay_overtime','احتساب مبلغ الإضافي في المرتب','Pay overtime amount in payroll','إذا اخترت لا تظهر ساعات الإضافي لكن المبلغ يكون صفر','If No: overtime hours still show, but overtime pay is zero',NULL,0,1,5,'2026-08-06 00:18:14');
